// init wires cross-schema edge references after all Schema vars are initialized
func init() {
	SchemaOrgMembership.Fields = []FieldDescriptor{
		{Name: "organization_id", Label: "OrganizationID", Type: "string", MatchKey: true, SystemControlled: true},
		{Name: "role", Label: "Role", Type: "enums.Role"},
		{Name: "user_id", Label: "UserID", Type: "string", MatchKey: true},
	}
	SchemaOrganization.Fields = []FieldDescriptor{
		{Name: "created_at", Label: "CreatedAt", Type: "time.Time", Clearable: true, SystemControlled: true},
		{Name: "created_by", Label: "CreatedBy", Type: "string", MatchKey: true, Clearable: true, SystemControlled: true},
		{Name: "description", Label: "Description", Type: "string", MatchKey: true, Clearable: true},
		{Name: "display_id", Label: "DisplayID", Type: "string", MatchKey: true},
		{Name: "name", Label: "Name", Type: "string", MatchKey: true},
		{Name: "preferences", Label: "Preferences", Type: "map[string]interface {}", Clearable: true, TaskRules: []TaskRuleDescriptor{{RuleID: "import-existing-policies", Expression: "value.policies.has_existing == true", Trigger: "createOnly"}, {RuleID: "framework", EachElement: "value.frameworks"}}},
		{Name: "updated_at", Label: "UpdatedAt", Type: "time.Time", Clearable: true, SystemControlled: true},
		{Name: "updated_by", Label: "UpdatedBy", Type: "string", MatchKey: true, Clearable: true, SystemControlled: true},
	}
	SchemaWorkflowInstance.Fields = []FieldDescriptor{
		{Name: "status", Label: "Status", Type: "string", WorkflowEligible: true, MatchKey: true, Clearable: true},
	}
	SchemaWorkflowObjectRef.Fields = []FieldDescriptor{
		{Name: "organization_id", Label: "OrganizationID", Type: "string", MatchKey: true, Clearable: true, SystemControlled: true},
		{Name: "workflow_instance_id", Label: "WorkflowInstanceID", Type: "string", MatchKey: true},
	}
	SchemaOrganization.TaskRules = []TaskRuleDescriptor{
		{RuleID: "setup-payment-method"},
	}
	SchemaOrgMembership.Edges = []EdgeDescriptor{
		{
			Name:        "organization",
			Label:       "Organization",
			Target:      SchemaOrganization,
			TargetType:  "Organization",
			Unique:      true,
			CreateField: "organization_id",
			Field:       "organization_id",
		},
	}
	SchemaWorkflowObjectRef.Edges = []EdgeDescriptor{
		{
			Name:             "organization",
			Label:            "Organization",
			Target:           SchemaOrganization,
			TargetType:       "Organization",
			Unique:           true,
			CreateField:      "organization_id",
			Field:            "organization_id",
			WorkflowEligible: true,
		},
		{
			Name:        "workflow_instance",
			Label:       "WorkflowInstance",
			Target:      SchemaWorkflowInstance,
			TargetType:  "WorkflowInstance",
			Unique:      true,
			CreateField: "workflow_instance_id",
			Field:       "workflow_instance_id",
		},
	}

	// through edges are linked by creating join entity rows — one per target, each with its own
	// generated id — so wrap the create and update closures of schemas that have them: through-edge
	// id lists are split out of the payload and applied as rows after the mutation succeeds
	for _, s := range allSchemas {
		if !slices.ContainsFunc(s.Edges, func(e EdgeDescriptor) bool { return e.Through }) {
			continue
		}

		schema := s

		if create := schema.Create; create != nil {
			schema.Create = func(ctx context.Context, client *generated.Client, input json.RawMessage) (string, error) {
				input, throughIDs := splitThroughEdgeIDs(schema, input)

				id, err := create(ctx, client, input)
				if err != nil {
					return id, err
				}

				return id, applyThroughEdgeIDs(ctx, client, schema, id, throughIDs)
			}
		}

		if update := schema.Update; update != nil {
			schema.Update = func(ctx context.Context, client *generated.Client, entityID string, input json.RawMessage) error {
				input, throughIDs := splitThroughEdgeIDs(schema, input)

				if err := update(ctx, client, entityID, input); err != nil {
					return err
				}

				return applyThroughEdgeIDs(ctx, client, schema, entityID, throughIDs)
			}
		}
	}
}

// splitThroughEdgeIDs removes through-edge id lists from a create or update payload, returning the
// cleaned payload and the target ids per edge name. Malformed values are left in place so input
// validation rejects them instead of being silently discarded
func splitThroughEdgeIDs(s *Schema, payload json.RawMessage) (json.RawMessage, map[string][]string) {
	if s == nil {
		return payload, nil
	}

	var ids map[string][]string

	cleaned := jsonx.EditObject(payload, func(doc map[string]json.RawMessage) bool {
		for _, edge := range s.Edges {
			if !edge.Through {
				continue
			}

			raw, ok := doc[edge.CreateField]
			if !ok {
				continue
			}

			targetIDs, err := jsonx.Decode[[]string](raw)
			if err != nil {
				continue
			}

			if ids == nil {
				ids = map[string][]string{}
			}

			ids[edge.Name] = targetIDs
			delete(doc, edge.CreateField)
		}

		return ids != nil
	})

	if ids == nil {
		return payload, nil
	}

	return cleaned, ids
}

// applyThroughEdgeIDs creates the join entity rows for each split through edge
func applyThroughEdgeIDs(ctx context.Context, client *generated.Client, s *Schema, sourceID string, ids map[string][]string) error {
	if s == nil || len(ids) == 0 {
		return nil
	}

	for name, targetIDs := range ids {
		edge, ok := s.EdgeByName(name)
		if !ok || edge.LinkThrough == nil || len(targetIDs) == 0 {
			continue
		}

		if err := edge.LinkThrough(ctx, client, sourceID, targetIDs); err != nil {
			return logError(ctx, SchemaRef{Schema: s.Snake, Operation: refOpLink, EntityID: sourceID, Edge: name}, ErrLinkFailed, err)
		}
	}

	return nil
}

// --- Lookup registry ---

var allSchemas = []*Schema{
	SchemaOrgMembership,
	SchemaOrganization,
	SchemaWorkflowInstance,
	SchemaWorkflowObjectRef,
}

var (
	schemaLookupOnce sync.Once
	schemaLookupMap  map[string]*Schema
)

func buildSchemaLookup() {
	schemaLookupOnce.Do(func() {
		schemaLookupMap = make(map[string]*Schema, len(allSchemas)*3)

		for _, s := range allSchemas {
			schemaLookupMap[s.Name] = s
			schemaLookupMap[s.Snake] = s
			schemaLookupMap[s.Lower] = s
		}
	})
}

// LookupSchema resolves a schema by any known name variation (PascalCase, snake_case,
// camelCase, or lowercase). Returns the schema and whether a match was found.
func LookupSchema(name string) (*Schema, bool) {
	buildSchemaLookup()

	if s, ok := schemaLookupMap[name]; ok {
		return s, true
	}

	if s, ok := schemaLookupMap[normalizeSchemaKey(name)]; ok {
		return s, true
	}

	return nil, false
}

// normalizeSchemaKey lowers a schema name and strips separators for fuzzy catalog lookup.
func normalizeSchemaKey(name string) string {
	return strings.ToLower(strings.NewReplacer("_", "", "-", "", " ", "").Replace(name))
}

// AllSchemas returns a copy of all registered schemas
func AllSchemas() []*Schema {
	result := make([]*Schema, len(allSchemas))
	copy(result, allSchemas)

	return result
}

// selectTargets queries entities matching a target selector and filters them with a typed CEL
// evaluator bound to the target schema's native projection — and, when the selector carries
// SourceContext with a SourceSchema, the source schema's projection as "source" — so selector
// expressions resolve typed fields rather than evaluating against a map[string]any
func selectTargets(ctx context.Context, client *generated.Client, orgID string, selector TargetSelector) ([]entityRef, error) {
	schema, ok := LookupSchema(selector.Schema.Name)
	if !ok {
		return nil, logError(ctx, SchemaRef{Schema: selector.Schema.Snake, Operation: refOpQuery}, ErrSchemaNotFound, fmt.Errorf("schema %s is not registered", selector.Schema.Name))
	}

	entities, err := selectCandidates(ctx, client, schema, orgID, selector)
	if err != nil {
		return nil, err
	}

	if selector.Unique && schema.InstanceScoped {
		pi := lookupValue(selector.SourceContext, FieldSourceInstanceID)

		entities = lo.Filter(entities, func(row json.RawMessage, _ int) bool {
			return lookupValue(row, FieldSourceInstanceID) == pi
		})
	}

	var (
		eval      *celx.NativeEntityEvaluator
		useSource bool
	)

	if selector.Expression != "" {
		if schema.ProjectionType == nil {
			return nil, fmt.Errorf("%w: %s has no projection for expression evaluation", ErrEvaluatorBuildFailed, schema.Name)
		}

		var sourceType reflect.Type

		if len(selector.SourceContext) > 0 && !selector.SourceSchema.IsZero() {
			if src, ok := LookupSchema(selector.SourceSchema.Name); ok && src.ProjectionType != nil {
				sourceType = src.ProjectionType
				useSource = true
			}
		}

		envCfg := celx.StrictEnvConfig()
		envCfg.CrossTypeNumericComparisons = true

		eval, err = celx.NewNativeEntityEvaluator(envCfg, celx.FastEvalConfig(), schema.ProjectionType, sourceType)
		if err != nil {
			errorEvent(ctx, SchemaRef{Schema: schema.Snake, Operation: refOpQuery}, err).Str(fieldExpression, selector.Expression).Msg(ErrEvaluatorBuildFailed.Error())

			return nil, fmt.Errorf("%w: %w", ErrEvaluatorBuildFailed, err)
		}

		logx.FromContext(ctx).Debug().Str(FieldSchema, schema.Snake).Str(fieldExpression, selector.Expression).Int("candidates", len(entities)).Msg("entityops: filtering targets with expression")
	}

	excludeSet := mapx.MapSetFromSlice(selector.ExcludeIDs)

	var results []entityRef

	for _, data := range entities {
		id := entityID(data)
		if id == "" {
			continue
		}

		if _, excluded := excludeSet[id]; excluded {
			continue
		}

		if selector.Expression != "" {
			var (
				match   bool
				evalErr error
			)

			if useSource {
				match, evalErr = eval.EvaluateBoolWithSource(ctx, selector.Expression, data, selector.SourceContext)
			} else {
				match, evalErr = eval.EvaluateBool(ctx, selector.Expression, data)
			}

			if evalErr != nil {
				errorEvent(ctx, SchemaRef{Schema: schema.Snake, Operation: refOpQuery, EntityID: id}, evalErr).Str(fieldExpression, selector.Expression).Msg(ErrEvaluationFailed.Error())
				continue
			}

			if !match {
				continue
			}
		}

		results = append(results, entityRef{ID: id, Schema: schema.SchemaDescriptor})
	}

	return results, nil
}

// selectCandidates resolves the candidate entity set for a target selector
func selectCandidates(ctx context.Context, client *generated.Client, schema *Schema, orgID string, selector TargetSelector) ([]json.RawMessage, error) {
	if selector.KeyMatch != nil {
		if schema.QueryByKey == nil {
			return nil, fmt.Errorf("%w: %s", ErrKeyMatchUnsupported, schema.Name)
		}

		values := collectKeyValues(selector.SourceContext, selector.KeyMatch)
		if len(values) == 0 {
			return nil, nil
		}

		if cache, ok := linkTargetCacheContextKey.Get(ctx); ok {
			return lookupLinkTargetCache(cache, schema.Snake, selector.KeyMatch.TargetField, values), nil
		}

		return schema.QueryByKey(ctx, client, orgID, selector.KeyMatch.TargetField, values)
	}

	if schema.Query == nil {
		return nil, fmt.Errorf("%w: %s", ErrQueryUnsupported, schema.Name)
	}

	return schema.Query(ctx, client, orgID)
}

// linkTargetCacheKey identifies one cached target lookup by target schema, field, and value
type linkTargetCacheKey struct {
	schema string
	field  string
	value  string
}

// linkTargetCache is the ctx-carried prefetch cache for link target rows
type linkTargetCache map[linkTargetCacheKey][]json.RawMessage

// linkTargetCacheContextKey carries the prefetch cache installed by PrefetchLinkTargets
var linkTargetCacheContextKey = contextx.NewKey[linkTargetCache]()

// lookupLinkTargetCache collects the cached rows for every value, deduplicated by entity id
func lookupLinkTargetCache(cache linkTargetCache, schemaSnake, field string, values []string) []json.RawMessage {
	seen := map[string]struct{}{}

	var rows []json.RawMessage

	for _, value := range values {
		for _, row := range cache[linkTargetCacheKey{schema: schemaSnake, field: field, value: value}] {
			id := entityID(row)
			if _, ok := seen[id]; ok {
				continue
			}

			seen[id] = struct{}{}
			rows = append(rows, row)
		}
	}

	return rows
}

// collectKeyValues extracts the deduplicated, non-empty source-side key values for a KeyMatch
// from the source entity JSON, combining the scalar SourceField with the SourceList values
func collectKeyValues(sourceContext json.RawMessage, km *KeyMatch) []string {
	if len(sourceContext) == 0 {
		return nil
	}

	var values []string

	if km.SourceField != "" {
		if value, ok := jsonx.DecodeObjectKey[string](sourceContext, km.SourceField); ok {
			values = append(values, value)
		}
	}

	if km.SourceList != "" {
		if list, ok := jsonx.DecodeObjectKey[[]string](sourceContext, km.SourceList); ok {
			values = append(values, list...)
		}
	}

	return lo.Uniq(lo.Without(values, ""))
}
